@startuml

class Driver {
  + DriverId : int
  + Name : string
  + IsOnSickLeave : boolean
}

class Bus {
  + LicensePlate : string
  + IsInRepairShop : boolean
}

class BusRoute {
  + RouteNumber : int
}

class Shift {
  + ShiftType : string
}

class Assignment {
  + Date : date
}

class CityStaff {}

CityStaff "1" -- "0..*" Driver : manages
CityStaff "1" -- "0..*" Bus : manages
CityStaff "1" -- "0..*" BusRoute : manages

BusRoute "1" o-- "0..*" Assignment
Bus "1" o-- "0..*" Assignment
Driver "1" o-- "0..*" Assignment
Assignment "1" -- "1" Shift

Bus "1" -- "0..*" BusRoute : assignedTo
@enduml

